fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    let initial_dist = (a - b).abs();
    let max_reachable = initial_dist + x;
    // The distance cannot exceed n - 1
    std::cmp::min(max_reachable, n - 1)
}

